sql.where:
 	T1.FINPROD_TYPE2 = #{assestType}
 	AND T1.TRADE_MARKET in(#{TRADE_PLACE_01})

	and T1.FINPROD_MARKET_ID = #{initValue}


	and T1.TRADE_MARKET = #{tradeMarket}


	and (T1.FINPROD_MARKET_ID like concat('%',concat(#{search},'%'))
	or T1.FINPROD_NAME like concat('%',concat(#{search},'%'))
	or T1.FINPROD_ABBR like concat('%',concat(#{search},'%'))
	or T1.FINPROD_ID like concat('%',concat(#{search},'%'))
	)

mapper.select:
SELECT DISTINCT A.PORTFOLIO_ID id, A.PORTFOLIO_NAME text, B.IS_GUARANTEE object, A.PROFIT_TYPE col FROM PTL_PORTFOLIO A LEFT JOIN PA_PTL_PORTFOLIO B ON A.PORTFOLIO_ID = B.PORTFOLIO_ID
(A.PORTFOLIO_ID LIKE CONCAT('%', CONCAT(#{search}, '%')) OR A.PORTFOLIO_NAME LIKE CONCAT('%', CONCAT(#{search}, '%')) )
AND A.PORTFOLIO_ID = #{initValue}
AND A.PORTFOLIO_TYPE = #{portType01}
AND A.INVEST_YESORNO = 'Y'
AND A.PORTFOLIO_TYPE != '02'
AND A.PORTFOLIO_TYPE = #{portfolioType}
and A.PORTFOLIO_ID in (select PORTFOLIO_ID from PTL_PORTFOLIO_AUTHORITY where USER_ID = #{loginUserName})
AND A.PORTFOLIO_TYPE IN (#{portType}, #{portType1})
AND B.PORTFOLIO_SERIES = #{portfolioSeries}
